import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"2018-May-17 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-May-17 :: Ceph Performance Weekly","date":"2018-05-17T00:00:00.000Z","updated":"2018-05-18T00:00:00.000Z","tags":["Ceph","Performance","Pull Requests","Blue Store","RocksDB"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-May-17_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-May-17_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),s={name:"posts/2018/2018-May-17_-_-_Ceph_Performance_Weekly.md"};function r(u,l,o,n,h,c){return a(),i("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>（此处应填写会议具体时间）</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><p>（此处应填写参会人员名单）</p><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>本周 Pull Requests 汇报及优先级缓存设计讨论</p><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><p><strong>1. 本周 Pull Requests 汇报</strong></p><ul><li><strong>新提交的 Pull Requests</strong>： <ul><li>提交了关于 Blue Store 优先级缓存的 Pull Requests，旨在简化用户设置内存使用比例的过程，并允许自动调优。</li></ul></li><li><strong>已合并的 Pull Requests</strong>： <ul><li>Igor 的 alligator pruning 修复 Pull Requests。</li><li>Async messenger Pull Requests，改进了锁定行为。</li><li>Overwrite apps 恢复优化 Pull Requests，未合并，作者已关闭。</li><li>Igor 的新位图分配器 Pull Requests，Sage 已审查，希望替换旧代码。</li><li>lib RBD throttle Pull Requests，更新情况不明。</li><li>Radice Slavs 的 crypto SSL Pull Requests，正在测试和修复中。</li></ul></li><li><strong>未合并的 Pull Requests</strong>： <ul><li>Peter 的 disc right coalescing Pull Requests。</li><li>Adam 的哈希相关 Pull Requests，Sage 的版本正在工作。</li><li>Peter 的减少 buffer list 重构的 Pull Requests。</li><li>Redick 的 huge pages Pull Requests。</li><li>Adam 的更多 Pull Requests。</li></ul></li><li><strong>其他</strong>： <ul><li>讨论了 AES 和加密相关的 Pull Requests。</li></ul></li></ul><p><strong>2. 优先级缓存设计讨论</strong></p><ul><li><strong>问题</strong>： <ul><li>用户难以调整缓存设置，且设置比例难以确定。</li><li>当 Blue Store 和 RocksDB 的缓存冲突时，性能会下降。</li><li>RocksDB 默认会扩展块缓存，可能会超过用户指定的比例，导致索引和过滤器被清除。</li></ul></li><li><strong>解决方案</strong>： <ul><li>提交的 Pull Requests 旨在简化用户设置内存使用比例的过程，并允许自动调优。</li><li>通过优先级方案，可以根据工作负载调整缓存分配。</li><li>未来工作包括： <ul><li>使用基于时间的优先级缓存，根据工作负载动态调整缓存分配。</li><li>在 OSD 级别进行缓存管理，考虑更多内存使用情况。</li><li>为不同的列族创建多个缓存，或为不同的前缀设置不同的优先级。</li></ul></li></ul></li></ul><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续推进优先级缓存设计，并解决相关问题和改进。</li><li>关注 RocksDB 的行为，并寻找解决方案以避免索引和过滤器被清除。</li><li>继续进行测试，并评估性能改进。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>与 Sage 商量，确认参会情况。</li><li>继续开发优先级缓存功能。</li><li>修复 RocksDB 相关问题。</li><li>进行更多测试和评估。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>本次会议讨论了本周 Pull Requests 和优先级缓存设计，并确定了后续行动计划。会议内容丰富，讨论深入，对 Ceph 的性能优化具有重要意义。</p>',18)])])}const P=e(s,[["render",r]]);export{p as __pageData,P as default};
